<script>
(function(){
  const board = document.getElementById('board');
  const frame = document.getElementById('mineFrame');
  const content = document.getElementById('content');
  const form = document.getElementById('customForm');
  const widthInput = document.getElementById('widthInput');
  const heightInput = document.getElementById('heightInput');
  const minesInput = document.getElementById('minesInput');
  const mineCount = document.getElementById('mineCount');
  const face = document.getElementById('face');
  const gameInfo = document.getElementById('gameInfo');
  let mode='beginner', width=9, height=9, mines=10, clicks=0;

  const presets={
    beginner:{w:9,h:9,m:10},
    intermediate:{w:16,h:16,m:40},
    expert:{w:30,h:16,m:99}
  };

  function buildBoard(revealed=false){
    board.innerHTML='';
    board.style.gridTemplateColumns=`repeat(${width},24px)`;
    board.style.gridTemplateRows=`repeat(${height},24px)`;
    board.style.width=(width*25+2)+'px';
    board.style.height=(height*25+2)+'px';
    frame.style.width=(width*25+30)+'px';
    clicks=0; gameInfo.classList.remove('visible'); face.textContent='🙂';
    mineCount.textContent=String(mines).padStart(3,'0');
    document.getElementById('timer').textContent='000';
    for(let r=0;r<height;r++){
      for(let c=0;c<width;c++){
        const cell=document.createElement('button');
        cell.className='btn cell';
        cell.dataset.r=r; cell.dataset.c=c;
        if(revealed && mode==='beginner'){
          const key=r+','+c;
          const vals={'0,0':'1','4,0':'2','4,1':'2','4,2':'2','4,3':'','4,4':'2','4,5':'1','4,6':'1','4,7':'1','4,8':'1','5,2':'1','5,3':'1','6,2':'1','6,3':'1','6,5':'1','6,6':'1','6,7':'1','7,5':'1'};
          if(vals[key]!==undefined){cell.classList.add('open',vals[key]?'n'+vals[key]:'');cell.textContent=vals[key]}
        }
        cell.addEventListener('click',()=>cellClick(cell));
        cell.addEventListener('contextmenu',e=>{e.preventDefault();cell.textContent=cell.textContent==='⚑'?'':'⚑';});
        board.appendChild(cell);
      }
    }
  }
  function cellClick(cell){
    if(cell.classList.contains('open')) return;
    clicks++;
    cell.classList.add('open');
    if(clicks===1){
      cell.classList.add('n2'); cell.textContent='2';
    }else if(clicks>1 && mode==='custom'){
      face.textContent='😵';
      document.querySelectorAll('.cell').forEach((x,i)=>{
        if(i%11===0 || i%17===0){x.textContent='✹';x.classList.add('mine')}
      });
      cell.classList.add('exploded'); cell.textContent='✹';
      gameInfo.classList.add('visible');
    }
  }
  function setMode(newMode){
    mode=newMode;
    document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.mode===mode));
    if(mode==='custom'){
      content.classList.add('custom-mode');
      form.classList.add('visible');
      width=parseInt(widthInput.value)||30;
      height=parseInt(heightInput.value)||30;
      mines=parseInt(minesInput.value)||150;
      buildBoard(false);
    }else{
      content.classList.remove('custom-mode');
      form.classList.remove('visible');
      width=presets[mode].w;height=presets[mode].h;mines=presets[mode].m;
      buildBoard(false);
    }
  }
  document.querySelectorAll('.tab').forEach(t=>t.addEventListener('click',()=>setMode(t.dataset.mode)));
  document.getElementById('updateBtn').addEventListener('click',()=>{
    width=Math.max(5,Math.min(40,parseInt(widthInput.value)||30));
    height=Math.max(5,Math.min(35,parseInt(heightInput.value)||20));
    mines=Math.max(1,parseInt(minesInput.value)||100);
    widthInput.value=width;heightInput.value=height;minesInput.value=mines;
    buildBoard(false);
  });
  face.addEventListener('click',()=>buildBoard(false));
  // Initial screenshot-like beginner board.
  buildBoard(true);
})();
</script>
